-- 早期管理端曾保存空的获奖荣誉模块；仅在 items 为空时恢复首页原有三张奖项卡片。
UPDATE homepage_content
SET content = '{"subText":"实验室荣誉","headText":"竞赛奖项.","description":"实验室鼓励成员积极参与各类学科竞赛，依托完善的技术指导体系，组织团队参与挑战杯、蓝桥杯、中国大学生计算机设计大赛等高水平学科赛事。","items":[{"name":"蓝桥杯大赛","description":"组织实验室成员组队参与蓝桥杯竞赛，覆盖 Java、C/C++ 主流赛道，依托常态化刷题训练与赛前集中辅导，多名成员斩获省级一、二、三等奖及全国总决赛奖项，夯实算法编程核心能力。","image":"","tags":[{"name":"算法竞赛","color":"blue-text-gradient"},{"name":"C++","color":"green-text-gradient"},{"name":"Java","color":"pink-text-gradient"}],"source_code_link":"https://github.com/"},{"name":"中国大学生计算机设计大赛","description":"围绕软件开发、人工智能、大数据等赛道组建参赛队伍，从选题、开发到作品打磨全程指导，锻炼完整项目开发与作品答辩能力。","image":"","tags":[{"name":"全栈开发","color":"blue-text-gradient"},{"name":"AI 项目","color":"green-text-gradient"},{"name":"作品答辩","color":"pink-text-gradient"}],"source_code_link":"https://github.com/"},{"name":"挑战杯科创竞赛","description":"聚焦科创创新课题，支持跨方向组队开展项目研发，培养创新思维与团队协作能力。","image":"","tags":[{"name":"科创项目","color":"blue-text-gradient"},{"name":"创新实践","color":"green-text-gradient"},{"name":"路演备赛","color":"pink-text-gradient"}],"source_code_link":"https://github.com/"}]}'::jsonb,
    updated_at = CURRENT_TIMESTAMP
WHERE module = 'works' AND COALESCE(jsonb_array_length(content->'items'), 0) = 0;
